3288a995-440e-47d6-9afb-4443c690a84b	homepage_layout	{"our_story": {"id": "our_story", "data": {"image": "https://res.cloudinary.com/qdq7ult5/image/upload/v1784136156/kalvix_nexus/uploads/rmjoznet5qcvxwxmfkxy.jpg", "title": "Our Story", "fitMode": "stretch", "mediaType": "image", "description": "Welcome to Divine Cardinal, where we embrace the 5,000-year-old tradition of Ayurveda to offer you holistic health and wellness solutions. Based in India, our brand is dedicated to bringing you the finest aromatherapy-based products, meticulously crafted from the purest natural ingredients.", "signatureText": "Gaurang Seksaria"}, "order": 9, "visible": true}, "brand_usps": {"id": "brand_usps", "data": {"items": [{"img": "https://res.cloudinary.com/qdq7ult5/image/upload/v1784136411/kalvix_nexus/uploads/uhpwysn1bqpaxkwxrkki.jpg", "desc": "Emphasize the 5,000-year-old tradition of Ayurveda and its holistic approach to health and wellness.", "title": "Ayurveda", "mediaType": "image"}, {"img": "https://res.cloudinary.com/qdq7ult5/image/upload/v1784136416/kalvix_nexus/uploads/mvqlrtewzm4djarcjjpo.jpg", "desc": "Aromatherapy-Based Fragrances: The therapeutic use of essential oils from plants for the improvement of physical, emotional, and spiritual well-being.", "title": "Aromatherapy", "mediaType": "image"}, {"img": "https://res.cloudinary.com/qdq7ult5/image/upload/v1784136430/kalvix_nexus/uploads/hnrshai6ppin2wtlmd5o.jpg", "desc": "Use of only natural ingredients, free from harsh chemicals, artificial fragrances, and dyes.", "title": "Natural Ingredients", "mediaType": "image"}, {"img": "https://res.cloudinary.com/qdq7ult5/image/upload/v1784136437/kalvix_nexus/uploads/dsikby10t6uqwxtub1pi.jpg", "desc": "Handcrafting each product, ensuring a personal touch and high-quality finish.", "title": "Handcrafted with Love", "mediaType": "image"}], "title": "Our Features"}, "order": 12, "visible": true}, "hero_banner": {"id": "hero_banner", "data": {"slides": [{"id": "slide-1783866416256", "title": "", "imageFit": "fill", "mediaUrl": "https://kalvix-nexus-production.up.railway.app/uploads/1783866420615-621835499.png", "mediaType": "image", "mobileMediaUrl": "https://res.cloudinary.com/qdq7ult5/image/upload/v1784124782/kalvix_nexus/uploads/juwtgugjiwu6vznwrprm.jpg"}, {"id": "slide-1784035548287", "title": "", "imageFit": "fill", "mediaUrl": "https://res.cloudinary.com/qdq7ult5/image/upload/v1784035563/kalvix_nexus/uploads/gctmje5mu6cbxhz2z9kv.png", "mediaType": "image", "mobileMediaUrl": "https://res.cloudinary.com/qdq7ult5/image/upload/v1784124606/kalvix_nexus/uploads/harholhlsieuvjuphze0.jpg"}, {"id": "slide-1784067689764", "title": "", "imageFit": "fill", "mediaUrl": "https://res.cloudinary.com/qdq7ult5/image/upload/v1784067710/kalvix_nexus/uploads/gy8pxx3pwkc6mdjsfahv.png", "mediaType": "image", "mobileMediaUrl": "https://res.cloudinary.com/qdq7ult5/image/upload/v1784124948/kalvix_nexus/uploads/ohe2jceyabkwsg0s2l93.jpg"}], "sliderInterval": 3}, "order": 1, "styles": {"textColor": "#1A1A1A", "fontFamily": "font-serif", "textAlignment": "left", "backgroundColor": "#FAF9F6"}, "visible": true}, "quiz_banner": {"id": "quiz_banner", "data": {"image": "data:image/jpeg;base64,", "title": "Beauty Routine", "subtitle": "Tailored", "questions": [{"key": "skinType", "options": ["Oily Skin", "Dry Skin", "Normal Skin", "Sensitive Skin"], "question": "What is your skin type?"}, {"key": "concern", "options": ["Clear Skin & Even Tone", "Muscle/Joint Pain", "Youthful Glow", "Baby Care"], "question": "What is your primary wellness concern?"}, {"key": "texture", "options": ["Light Hydrating Serum", "Nourishing Massage Oil", "Concentrated Face Serum", "Pure Flower Mist"], "question": "Which product texture do you prefer?"}], "buttonText": "Take the Quiz", "description": "Answer a few simple questions to discover your personalized Ayurvedic ritual tailored specifically to your dosha, skin type and lifestyle needs.", "recommendations": [{"productSku": "DCIWN09", "conditionKey": "concern", "conditionValue": "Muscle/Joint Pain"}, {"productSku": "DCIW01", "conditionKey": "concern", "conditionValue": "Clear Skin & Even Tone"}, {"productSku": "DCIWN30", "conditionKey": "texture", "conditionValue": "Pure Flower Mist"}, {"productSku": "DCIW02", "conditionKey": "default", "conditionValue": "default"}]}, "order": 7, "visible": true}, "slow_beauty": {"id": "slow_beauty", "data": {"title": "RITUALS ARE NEVER RUSHED", "mediaType": "video", "buttonLink": "/pages/about", "buttonText": "Explore Now", "videoImage": "https://res.cloudinary.com/qdq7ult5/video/upload/v1784135324/kalvix_nexus/uploads/m1cdf34vc27rqsouylvc.mp4", "description": "A reminder to savour the stillness between moments, pause long enough to feel, ease into your own rhythm, release the urgency and take your time as life gently unfolds.", "videoSubtitle": "", "videoTitleLine1": "", "videoTitleLine2": ""}, "order": 2, "visible": true}, "best_sellers": {"id": "best_sellers", "data": {"title": "BEST SELLERS", "subtitle": "Most Loved", "productIds": ["DCIC18", "DCIW12", "DCIW10", "DCIFB01", "DCIWN05"], "description": "Explore our highly rated, time-tested health & body care remedies."}, "order": 3, "visible": true}, "latest_reads": {"id": "latest_reads", "data": {"items": [{"date": "July 8, 2026", "image": "https://res.cloudinary.com/qdq7ult5/image/upload/v1784136069/kalvix_nexus/uploads/ru5tv7ov4fodwn5vtgpf.jpg", "title": "NOTHING MEANT TO BE WASTED", "content": "At Divine Cardinal, we believe that true luxury is sustainable. Every single component of our raw material procurement, extraction, and packaging process is aligned with ecological conservation. Our glass jars are completely recyclable, and our organic residue from cold-pressing oils is safely composted and returned to the farmers to enrich the soil for subsequent crops. Guided by the principles of zero-waste Ayurveda, we celebrate the absolute cycle of nature.", "category": "Sustainability", "mediaType": "image"}, {"date": "June 28, 2026", "image": "https://res.cloudinary.com/qdq7ult5/image/upload/v1784136078/kalvix_nexus/uploads/bo7lp1x3x1po1dviyqki.jpg", "title": "EVERY DROP, THOUGHTFULLY RETURNED", "content": "Water conservation lies at the core of our manufacturing processes. In our steam-distillation rituals, every single drop of condensation is collected, cooled, and processed through state-of-the-art filtration. We use closed-loop water systems that reuse cooling water, preventing millions of liters of water wastage each year. Our commitment is simple: what we take from the earth, we return with absolute purity.", "category": "Sustainability", "mediaType": "image"}, {"date": "May 14, 2026", "image": "https://res.cloudinary.com/qdq7ult5/image/upload/v1784136087/kalvix_nexus/uploads/dnwy7bixfmi4yzypkyfw.jpg", "title": "POWERED BY THE SUN, GUIDED BY INTENTION", "content": "Our extraction units and offices run entirely on solar energy grids. Nestled in the sunlit foot-hills of the Himalayas, our solar arrays harvest clean, renewable energy to power the cold-pressing expellers and distillation boilers. We choose to minimize our carbon footprint, ensuring that every time you nourish your skin with Divine Cardinal, you are participating in a clean, solar-driven future for India and the world.", "category": "Brand Story", "mediaType": "image"}], "title": "Latest Reads", "buttonLink": "/blogs/journal", "buttonText": "Read Blog >"}, "order": 8, "visible": true}, "trusted_tales": {"id": "trusted_tales", "data": {"items": [{"img": "https://res.cloudinary.com/qdq7ult5/video/upload/v1784135664/kalvix_nexus/uploads/wzzqurspeujsnsx1cbvn.mp4", "desc": "", "likes": 120, "price": "", "title": "Luxary Face Serum", "mediaType": "video"}, {"img": "https://res.cloudinary.com/qdq7ult5/video/upload/v1784135781/kalvix_nexus/uploads/mvw6i2wytwuzyg4dpuve.mp4", "desc": "The skin requires a gentle boost after cleansing to rehydrate, tone and...", "likes": 340, "price": "", "title": "Facial Tonic Mist Pure